mapper.update:
UPDATE submissions
SET status = #{status},
    time_used_ms = #{timeUsedMs},
    memory_used_kb = #{memoryUsedKb},
    compile_message = #{compileMessage},
    judge_message = #{judgeMessage},
    judged_at = #{judgedAt}
WHERE id = #{id}
  AND claim_token = #{claimToken}
  AND status = 'JUDGING'

UPDATE submissions
SET lease_expires_at = #{leaseExpiresAt}
WHERE id = #{id}
  AND claim_token = #{claimToken}
  AND status = 'JUDGING'
  AND lease_expires_at > #{now}
